def find_connected_regions(grid):
    """Find all 4-connected regions of the same color"""
    H, W = len(grid), len(grid[0])
    visited = [[False]*W for _ in range(H)]
    regions = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                region_cells = []
                q = deque([(r,c)])
                visited[r][c] = True

                while q:
                    cr, cc = q.popleft()
                    region_cells.append((cr, cc))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                regions.append((color, region_cells))

    return regions

def is_rectangular_border(color, cells, H, W):
    """Check if cells form a complete rectangular border"""
    if not cells:
        return False

    rs = sorted([c[0] for c in cells])
    cs = sorted([c[1] for c in cells])
    rmin, rmax = rs[0], rs[-1]
    cmin, cmax = cs[0], cs[-1]

    # Expected number of border cells
    expected = 2 * (rmax - rmin + 1) + 2 * (cmax - cmin + 1) - 4

    # Check all cells in the rectangle are actually the border color
    rect_cells = set(cells)
    for r in range(rmin, rmax+1):
        for c in range(cmin, cmax+1):
            if (r, c) not in rect_cells:
                return False

    # Check interior is empty (either 0 or other colors permit nested boxes)
    for r in range(rmin+1, rmax):
        for c in range(cmin+1, cmax):
            if (r, c) in rect_cells:
                return False  # Interior cell shouldn't be border color

    return len(cells) == expected

