        interior_area = (rmax - rmin - 1) * (cmax - cmin - 1)
        sorted_boxes.append((color, rmin, rmax, cmin, cmax, interior_area))
sorted_boxes.sort(key=lambda x: -x[5])

print(f"Valid boxes: 4={boxes_by_type[4]}, 6={boxes_by_type[6]}, 8={boxes_by_type[8]}")

for color, rmin, rmax, cmin, cmax, area in sorted_boxes:
    fill_c = fill_color(color)
    r_start, r_end = rmin + 1, rmax - 1
    c_start, c_end = cmin + 1, cmax - 1

    if color == 6:
        for r in range(r_start, r_end + 1):
            for c in range(c_start, c_end + 1):
                result[r][c] = 0
    elif color == 8:
        for r in range(r_start, r_end + 1):
            for c in range(c_start, c_end + 1):
                int_row, int_col = r - r_start, c - c_start
                if (int_row + int_col) % 2 == 0:
                    result[r][c] = fill_c
    elif color == 4:
        for r in range(r_start, r_end + 1):
            for c in range(c_start, c_end + 1):
                int_row, int_col = r - r_start, c - c_start
                last = r_end - r_start
                use_A = int_row % 2 == 0 or int_row == last
                c_ones = [1, 3] if use_A else [2, 3]
                if int_col in c_ones:
                    result[r][c] = fill_c

for color, cells in regions:
    if color in [4, 6, 8]:
        rs = sorted([c[0] for c in cells])
        cs = sorted([c[1] for c in cells])
        for r in range(rs[0], rs[-1] + 1):
            for c in range(cs[0], cs[-1] + 1):
                if input_grid[r][c] == color:
                    result[r][c] = color

# Compare
expected = demos[0]["output"]
matches = sum(1 for r in range(18) for c in range(23)
              if expected[r][c] == result[r][c])
print(f"Score: {matches}/414")

mismatches = []
for r in range(18):
    for c in range(23):
        if expected[r][c] != result[r][c]:
            mismatches.append(((r,c), expected[r][c], result[r][c], input_grid[r][c]))
print(f"Total mismatches: {len(mismatches)}")

# Show mismatches by row
for r in range(18):
    row_m = [m for m in mismatches if m[0][0] == r]
    if row_m:
        print(f"\nRow {r}:")
        print(f"  Expected: {[e[1] for e in row_m]}")
        print(f"  Got: {[e[2] for e in row_m]}")
        print(f"  Input: {[e[3] for e in row_m]}")
